sols=[]
for combo in itertools.combinations_with_replacement(cands, len(nineO)):
    occ=collections.Counter()
    ok=True
    for off in combo:
        for p in nineI:
            pos=(off[0]+p[0], off[1]+p[1])
            if not (0<=pos[0]<4 and 0<=pos[1]<4): ok=False;break
            occ[pos]+=1
        if not ok: break
    if ok and Counter(pts)-collections.Counter(set(pos for off in combo for p in nineI for pos_ in [(off[0]+p[0], off[1]+p[1])]))==Counter() and not any(v>1 for v in occ.values()):
        sols.append(combo)
